counts = {}
total = 0
for name in ["a.txt", "b.txt"]:
    c = repo.read("data/" + name)
    lines = c.split("\n")
    if lines and lines[-1] == "":
        lines = lines[:-1]
    counts[name] = len(lines)
    total += len(lines)
wc = env.run(["wc", "-l", "data/a.txt", "data/b.txt"], check=False)
return {"counts": counts, "total": total, "wc": wc.stdout}
